struct Base { int x; };
struct Derived : Base {};

// Pointer to member types
using PTM_B = int Base::*;
using PTM_D = int Derived::*;

PTM_D d_ptr = &Derived::x;

// Upcasting (implicit conversion allowed)
PTM_B b_ptr = d_ptr;

Derived obj;
(obj.*b_ptr) = 42; // Usage via base pointer

// --- Null Conversion ---

struct Data { double d; };
using PTM = double Data::*;

// Conversion to null pointer to member
PTM null_pm = nullptr;

// Null check
if (null_pm == 0) {
    // Pointers to members can be null
}

// Any integer literal 0 converts to null PTM
PTM zero_pm = 0;
// null_pm == zero_pm is true
